<script>document.addEventListener('DOMContentLoaded',()=>{const list=document.querySelector('[data-quote-items]');let i=1;document.querySelector('[data-add-quote-item]')?.addEventListener('click',()=>{const row=document.createElement('div');row.className='quotation-item';row.innerHTML=`<input name="items[${i}][description]" placeholder="وصف القطعة أو الخدمة" required><input name="items[${i}][quantity]" type="number" step="0.001" min="0.001" value="1" required><input name="items[${i}][unit_price]" type="number" step="0.01" min="0" placeholder="السعر" required><button type="button" data-remove-quote-item>×</button>`;i++;list.append(row)});list?.addEventListener('click',e=>{if(e.target.matches('[data-remove-quote-item]')&&list.children.length>1)e.target.parentElement.remove()})});</script>
